"""Build the self-contained Senyap presentation from the product design tokens."""
from pathlib import Path
from html import escape
import base64

ROOT = Path(__file__).parent
def asset(name):
    return 'data:image/png;base64,' + base64.b64encode((ROOT/'deck-assets'/name).read_bytes()).decode()
def card(title, body, cls=''):
    return f'<article class="card {cls}" data-check><h3>{title}</h3><p>{body}</p></article>'
def grid(*cards):
    return '<div class="grid">'+''.join(cards)+'</div>'
slides=[]
def slide(title, body, note='', night=False):
    n=len(slides)+1
    slides.append(f'<section data-document-role="page" data-label="{escape(title)}" data-speaker-notes="{escape(note)}" class="page {"night" if night else ""}"><header><span class="brand"><i></i><b></b><em></em> Senyap</span><span>Midnight · Wave 2</span></header><main><h1 data-check>{title}</h1>{body}</main><footer><span>Senyap · Private signals with accountable stakes</span><span>{n:02d}</span></footer></section>')

slide('Hear the signal.<br><span class="gold">Never the source.</span>',f'<div class="hero-copy"><p>A private signal market on Midnight. Insiders back an option with refundable stakes. Buyers pay to open the combined signal.</p><div class="pill">Built on Midnight Preprod <span>↗</span></div></div><div class="vault"><img src="{asset("landing.png")}" alt="Original Senyap vault artwork"></div>', 'Working prototype, not a promise of complete anonymity. Public funding and operator trust boundaries are explained on slide 12.', True)
slide('The evidence is there.<br>The useful context is harder to reach.',grid(card('Ecosystems need better sourcing','Grant teams need to identify builders worth supporting, beyond the quality of a public application.'),card('Builders need operational context','Builders need to assess audit support, responsiveness and the working experience inside an ecosystem.'))+'<div class="band"><h3>The product hypothesis</h3><p>People with useful first-hand context may avoid attaching their name to a candid recommendation. A private, stake-backed signal could make that context usable.</p></div>', 'This privacy and willingness-to-pay hypothesis has not yet been validated through customer interviews.')
slide('A documented workflow problem.<br>A privacy hypothesis still to test.',grid(card('Sourcing quality','Plurality Labs’ milestone review identifies sourcing quality grant applications as a major risk.<small>Arbitrum forum · Plurality Labs · 2024</small>'),card('Fragmented operations','ARDC’s grant recommendations describe fragmented communication and occasional disbursement delays or errors.<small>Arbitrum forum · Castle Labs + DefiLlama Research · 7 Mar 2025</small>'))+'<div class="note">These reports support the workflow problem. They do not establish demand for Senyap, privacy preferences or willingness to pay.</div>', 'Sources https://forum.arbitrum.foundation/t/plurality-labs-milestone-1-review/20198 and https://forum.arbitrum.foundation/t/recommendations-for-improving-the-dao-s-grant-programs/28645. See source appendix for links.')
slide('One signal market.<br>Two directions of discovery.',grid(card('Side A · Find builders','Ecosystems assess opt-in builder teams. A sealed two-slot auction sells early exclusivity, followed by per-option purchases.'),card('Side B · Find ecosystems','Builders assess ecosystem experience. Flat purchases open aggregate support and reasons, with a bounded subsidy from Side A.'))+'<div class="band"><h3>Accountability without a public pick</h3><p>Scouts stake demo dUSD, submit an encrypted pick and reason, then prove a qualifying hit to claim rewards. Cancellation paths protect eligible principal.</p></div>')
slide('A complete market loop.', '<div class="steps">'+''.join(f'<div class="step"><strong>{i:02d}</strong><h3>{a}</h3><p>{b}</p></div>' for i,(a,b) in enumerate([('Join','Credential-backed admission and private membership.'),('Back','An encrypted option and reason, backed by a 10–500 demo dUSD stake.'),('Aggregate','At least five scouts before an eligible preview.'),('Open','A buyer pays, then receives verified decryption shares.'),('Resolve','An outcome enables a private hit proof and claim, or an eligible refund.')],1))+'</div><div class="note">Up to eight options and three positions per scout. Staking is an incentive mechanism, not a guarantee that a signal is true.</div>')
slide('The paid signal opens<br>inside the real product.',f'<div class="ui-frame"><img src="{asset("purchases.png")}" alt="Recorded purchase page, market 7"></div><div class="split-caption"><h3>Market #7 · Owner browser purchase</h3><p>The recorded page opens aggregate weight 235 and one reason after a 10 dUSD purchase. This is a demo market with synthetic content.</p></div>', 'Original product recording, scene8-purchases.mp4 at 25 seconds. Market 7 is separate from the complete settled market 3 lifecycle. Landing-page example numbers are illustrative, not network metrics.')
slide('A small interface.<br>An explicit technical stack.', '<div class="architecture"><div class="node"><h3>React + Vite + TypeScript</h3><p>Role-based actions, activity, purchases and recovery UI</p></div><div class="node"><h3>Lace + Midnight.js SDK</h3><p>Wallet balance, sign and submit · typed client · receipt reconciliation</p></div><div class="row">'+card('Compact contract','52 circuits · lifecycle, private membership, encrypted tally, payments, hits and claims')+card('Midnight Preprod','Public ledger + ZK verification · public RPC and indexer · separate demo dUSD contract')+'</div><div class="row">'+card('Local proof server','Heavy proofs use private witnesses supplied to the local prover')+card('Operator + relay + committee','Reason screening, encrypted delivery, previews and 3-of-5 share release')+'</div></div>', 'Compact 0.31.1, runtime 0.16.0, proof server 8.1.3, Midnight.js 4.1.1. Local service model, not all proving in the browser. Metadata hashes are verified. Asset preparation checks source and proving-key alignment.')
slide('Private inputs.<br>Verifiable state changes.',grid(card('Membership + nullifiers','ZK membership checks and scoped nullifiers constrain access and prevent reuse without publishing the identity secret.'),card('Encrypted aggregation','Encrypted picks accumulate support. Range bounds keep the aggregate within the configured decoding space.'),card('Threshold delivery','Joint Shamir key generation and Feldman-style commitments. Buyer-bound shares are checked with DLEQ before decoding.'))+'<div class="note">Reclaim admission is demonstrated for a logged-in account. It is not a verified contribution count or a complete Sybil defense.</div>', 'Funding wallets and amounts remain public. DLEQ rejection is off-chain. Wrong-share slashing is not enforced. All demo shares are controlled by the owner.',True)
slide('Deployed. Executed. Traceable.', '<div class="stats"><div><strong>52</strong><p>Contract circuits</p></div><div><strong>157</strong><p>Indexed finalized actions</p></div><div><strong>7</strong><p>Side B markets created</p></div></div><div class="band"><h3>Market #3 completed the Side B lifecycle</h3><p>Create, five sealed stakes, close, preview approvals, buyer purchase, outcome, five private hit proofs and five claims.</p></div><div class="note">Evidence snapshot · 19 Oct 2026. Actions are not users or traction. The owner controls operator and committee seats. Scouts are synthetic identities.</div>', 'Deployment a79019329f23d638ea7c690bf4fc8c9da6e60b6f7b3951cbf35ead11b8267ff9. Source docs/evidence/preprod-transactions.json and F5-preprod-market-3-journal.json. Other owner browser evidence uses markets 6 and 7.')
slide('Quality includes failure<br>and recovery.',grid(card('Contract and crypto','Membership misuse, nullifier replay, range limits, lifecycle gates, malformed shares and payment conservation.'),card('Operational failures','Missing receipts, stale snapshots, submission ID formats, retries and explicit late-receipt reconciliation.'),card('Product behavior','Wrong roles, expired windows, wallet action states, purchase opening, responsive layouts and privacy explanations.'))+'<div class="band"><h3>Evidence comes from several layers</h3><p>Focused regression run · 44 tests across 11 files passed. Full CI · 66 test files passed. Local lifecycle journals and finalized Preprod receipts provide separate integration evidence.</p></div>', 'See docs/evidence/demo-video-qa-review-2026-10-19.json and GitHub Actions run 39196182087. Counts describe specific runs. This is engineering QA, not an independent security audit.')
slide('Test the economic paths.<br>Keep the versions visible.',grid(card('Full local cycle · r10','84 actions, both market sides settled. Conservation checked with 1,240 received = 1,120 claims + 100 refund + 20 remainder.<small>Historical 42-circuit source · 4f1b3390</small>'),card('Current local cycle · short-s2','67 transactions. Cancellation, 500 refund, retained 1,750, listed intent, opt-out and leaked-share seizure recorded.<small>Current 52-circuit source · edb4251f</small>'))+'<div class="note">The current short cycle is a cancellation and enforcement exercise. It is not a replacement claim of full settlement on both sides.</div>', 'Sources docs/evidence/local-product-cycle-fresh-k16-r10-journal.json and local-product-cycle-short-s2-journal.json. Verify exact file paths in the accompanying progress document.')
slide('The trust boundaries<br>are part of the product.',grid(card('Public funding','Unshielded demo dUSD exposes funding wallets and amounts. No network-level anonymity claim.'),card('Readable reasons','The reason operator and Gemini screening can see submitted reason text. Screening does not prove truth.'),card('Committee control','Three colluding shares can decrypt. Five local processes are controlled by one owner today.'))+'<div class="note">No independent audit, independent committee, paying customer or pilot is claimed. Operator vote timing and production hardening remain open work.</div>', 'These constraints are intentionally disclosed before a pilot. Heavy-circuit local proving is also a witness-handling trust boundary.')
slide('Access pays for signal.<br>Scouts share the upside.', '<div class="business"><div class="allocation"><strong>85%</strong><p>Qualifying scout rewards</p><strong class="small">15%</strong><p>Platform allocation</p></div><div>'+card('Who pays','Ecosystem teams on Side A and builders on Side B pay to open useful aggregate signals.')+card('How the sides connect','Up to five percentage points of Side A revenue can support Side B. Side B subsidy goes to scout rewards.')+'</div></div><div class="note">Mechanism parameters and pricing are hypotheses. Demo dUSD is a test token. Revenue and willingness to pay have not been demonstrated.</div>')
slide('The next milestone<br>is a useful opt-in trial.',grid(card('Validate the need','Interview builders and ecosystem teams, test the sourcing problem and ask what decision a paid signal would change.'),card('Reduce operational trust','Separate committee ownership, review reason privacy and audit sensitive contract and proof paths.'),card('Measure a pilot','Track eligible participation, signal usefulness, purchase intent and repeat use. Set success thresholds with participants first.'))+'<div class="band"><h3>Prior work, disclosed</h3><p>The idea and market mechanism carry over from Bisik, submitted to Colosseum on 13 Oct 2026. Senyap’s Midnight implementation was written during Wave 2. Solana, Arcium and Semaphore code is absent from this repo.</p></div>')
slide('A signal worth opening.<br><span class="gold">A source worth protecting.</span>', '<p class="closing">Senyap turns private conviction into an aggregate signal with accountable stakes and visible trust boundaries.</p><div class="pill">Working Midnight Preprod prototype <span>↗</span></div><div class="closing-links">github.com/scientivan/senyap<br>README · Network receipts · QA evidence · Demo video</div>', 'Repository remains private until the owner publishes it. Demo video upload and publicly accessible deck link must be checked before submission.',True)
slide('Sources and verification.', '<div class="sources"><h3>Problem evidence</h3><p><a href="https://forum.arbitrum.foundation/t/plurality-labs-milestone-1-review/20198">Plurality Labs milestone 1 review · Arbitrum forum</a><br><a href="https://forum.arbitrum.foundation/t/recommendations-for-improving-the-dao-s-grant-programs/28645">Recommendations for improving DAO grant programs · ARDC</a></p><h3>Implementation and technical receipts</h3><p><a href="https://github.com/scientivan/senyap">github.com/scientivan/senyap</a><br>README.md · docs/evidence/PREPROD-EVIDENCE.md<br>docs/evidence/preprod-transactions.json<br>docs/submission/wave-2-progress-draft.md</p><h3>QA</h3><p><a href="https://github.com/scientivan/senyap/actions/runs/39196182087">Full CI run 39196182087</a><br>docs/evidence/demo-video-qa-review-2026-10-19.json<br>Versioned local product-cycle journals</p></div>', 'Evidence snapshot 19 Oct 2026. Repository links require access until owner publication. Public access must be verified before submission.')

css='''
*{box-sizing:border-box}html,body{margin:0;background:#EBE7E7;color:#2A1B1B;font-family:-apple-system,BlinkMacSystemFont,'SF Pro Display','SF Pro Text',Inter,'Helvetica Neue',sans-serif} .page{width:1600px;height:900px;background:white;position:relative;overflow:hidden;page-break-after:always;padding:44px 72px 45px}.night{background:#2A1B1B;color:#F4EFEF;background-image:radial-gradient(#4B3838 1px,transparent 1px);background-size:32px 32px}header,footer{display:flex;justify-content:space-between;align-items:center;font-size:18px;font-weight:500}header{height:38px}header>span:last-child{color:#8A7B7B}.brand{font-size:26px;display:flex;align-items:center;gap:5px}.brand i,.brand b,.brand em{display:inline-block;width:5px;border-radius:3px;background:#AE9970;height:23px}.brand b{height:16px;background:#C1272D}.brand em{height:9px;background:#A50C22;margin-right:10px}main{margin-top:60px}h1{font-size:76px;line-height:1.05;letter-spacing:-.035em;font-weight:300;margin:0 0 40px;max-width:1430px}h3{font-size:27px;line-height:1.2;font-weight:500;margin:0 0 20px;letter-spacing:-.02em}p{font-size:25px;line-height:1.45;font-weight:400;margin:0;color:#5B4646;text-align:justify}.grid{display:flex;gap:24px}.card{border:1px solid #E4DFDF;border-radius:18px;background:#F5F3F3;padding:30px;flex:1;min-width:0}.card p{font-size:24px}.card small{display:block;font-size:18px;line-height:1.5;margin-top:22px;color:#6A5A38}.band{background:#2A1B1B;color:#F4EFEF;padding:30px 36px;border-radius:28px;margin-top:26px}.band p,.night p{color:#CDBFBF}.note{font-size:22px;line-height:1.45;background:#F5F3F3;padding:24px 30px;border-radius:18px;margin-top:26px;color:#5B4646}.night .card,.night .note{background:#352323;border-color:#4B3838;color:#CDBFBF}.night h3{color:#F4EFEF}.night small{color:#D9CDB4}footer{position:absolute;bottom:34px;left:72px;right:72px;font-size:17px;color:#8A7B7B}.night footer,.night header>span:last-child{color:#CDBFBF}.gold{color:#AE9970}.hero-copy{max-width:650px;position:relative;z-index:2}.hero-copy p{font-size:29px}.pill{background:#C1272D;color:white;border-radius:50px;padding:18px 20px 18px 28px;display:inline-flex;gap:35px;align-items:center;font-size:21px;font-weight:500;margin-top:32px}.pill span{border-radius:50%;background:white;color:#C1272D;width:36px;height:36px;display:grid;place-items:center;font-size:25px}.vault{position:absolute;right:40px;top:245px;width:730px;height:440px;overflow:hidden;border-radius:28px}.vault img{position:absolute;width:1730px;max-width:none;left:-1010px;top:-150px}.steps{display:flex;gap:16px}.step{flex:1;background:#F5F3F3;border:1px solid #E4DFDF;border-radius:18px;padding:24px 20px}.step strong{font-size:48px;font-weight:800;color:#AE9970}.step h3{margin-top:25px}.step p{font-size:22px;text-align:left}.ui-frame{border:1px solid #E4DFDF;border-radius:18px;padding:8px;background:#F5F3F3;height:350px;overflow:hidden}.ui-frame img{width:2100px;max-width:none;display:block;border-radius:12px;margin-left:-330px}.split-caption{display:grid;grid-template-columns:1fr 1fr;gap:32px;margin-top:28px}.split-caption p{font-size:23px}.architecture{display:flex;flex-direction:column;gap:13px}.node{background:#F5F3F3;border:1px solid #E4DFDF;padding:16px 25px;border-radius:18px;display:flex;justify-content:space-between;align-items:center;gap:30px}.node h3{margin:0;font-size:25px}.node p{font-size:21px;text-align:right}.row{display:flex;gap:20px}.architecture .card{padding:21px 25px}.architecture .card h3{font-size:25px;margin-bottom:10px}.architecture .card p{font-size:22px}.stats{display:flex;gap:80px;margin:20px 0 50px}.stats>div{flex:1}.stats strong{font-size:118px;letter-spacing:-.05em;font-weight:800;line-height:1}.stats p{margin-top:15px;font-size:25px}.business{display:grid;grid-template-columns:.8fr 1.4fr;gap:50px}.business .card{margin-bottom:20px;padding:24px}.allocation{background:#2A1B1B;color:#AE9970;border-radius:28px;padding:25px 40px}.allocation strong{font-size:95px;font-weight:800;line-height:1}.allocation .small{font-size:64px;display:block;margin-top:23px}.allocation p{color:#F4EFEF;font-size:24px;text-align:left}.closing{max-width:1000px;font-size:32px}.closing-links{font-size:23px;line-height:1.8;margin-top:50px;color:#CDBFBF}.sources{display:grid;grid-template-columns:1fr 1.3fr;gap:20px 45px}.sources h3{margin:0}.sources p{font-size:24px;text-align:left;line-height:1.55}.sources a{color:#6A5A38;text-decoration:none}@page{size:1600px 900px;margin:0}@media print{html,body{background:white}.page{break-after:page}}
'''
(ROOT/'senyap-deck.html').write_text('<!DOCTYPE html><html lang="en"><meta charset="utf-8"><title>Senyap · Wave 2</title><style>'+css+'</style><body>'+''.join(slides)+'</body></html>')
(ROOT/'deck-outline.md').write_text('# Senyap slide deck\n\nGenerated from the actual product design tokens and recorded UI. Editorial snapshot 19 Oct 2026.\n\n'+ '\n\n'.join(f'## {i+1}. '+s.split('data-label="')[1].split('"')[0].replace('&lt;br&gt;',' ').replace('&lt;span class=&quot;gold&quot;&gt;','').replace('&lt;/span&gt;','') for i,s in enumerate(slides))+'\n\nSource and presenter notes are embedded in `senyap-deck.html`. Build with `python3 docs/submission/build-deck.py`. Export with the local browser helper in `video/remotion/deck-browser.mjs export`.\n')
print(f'Built {len(slides)} slides')
